<?php
declare(strict_types=1);
require __DIR__.'/../../public/api/_planner_core.php';require __DIR__.'/../../public/api/_planner_schema.php';require __DIR__.'/../../public/api/_planner_reports.php';
$n=0;function check(bool $v,string $why):void{global $n;$n++;if(!$v)throw new RuntimeException($why);}
check(cssv_planner_day(new DateTimeImmutable('2026-10-07T18:59:59Z'))==='2026-10-07','Before Karachi midnight');check(cssv_planner_day(new DateTimeImmutable('2026-10-07T19:00:00Z'))==='2026-10-08','Karachi midnight');
